        remaining_symbols = set()
        for n in nodes:
            if n['id'] not in removed_set and n['id'] != cid:
                remaining_symbols.add(n['symbol'])
        if required_symbols.issubset(remaining_symbols):
            removed_set.add(cid)
            removed_order.append(cid)
    # Build retained set sorted alphabetically
